hl.on("config.reloaded", function()
    hl.exec_cmd("cp -L --no-preserve=mode --update=none ~/.config/hypr/scheme/default.conf ~/.config/hypr/scheme/current.conf")
    hl.exec_cmd("~/.config/hypr/scripts/configs.fish ~/.config/caelestia")
end)


